import { createKvServer } from './server.js';

const arg = process.argv[2];
const port = Number(arg);
if (!Number.isInteger(port) || port < 0 || port > 65535) {
  console.error(`usage: app <port>  (got ${JSON.stringify(arg)})`);
  process.exit(2);
}

const server = createKvServer();
server.on('error', (err) => {
  console.error(`server error: ${err.message}`);
  process.exitCode = 1;
});
server.listen({ port, host: '127.0.0.1', backlog: 1024 });

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.once(signal, () => {
    server.close();
    server.closeAllConnections();
  });
}

import { createServer } from 'node:http';
import { Store } from './store.js';

export const MAX_VALUE_BYTES = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,64}$/;
const KV_PREFIX = '/kv/';

class HttpError extends Error {
  constructor(status) {
    super(String(status));
    this.status = status;
  }
}

function send(res, status, body = '', headers = {}) {
  const buf = typeof body === 'string' ? Buffer.from(body) : body;
  res.writeHead(status, { ...headers, 'Content-Length': buf.length });
  res.end(buf);
}

function methodNotAllowed(res, allowed) {
  send(res, 405, '', { Allow: allowed.join(', ') });
}

/** Reads the full request body, rejecting with 413 past the size limit. */
async function readBody(req, limit) {
  const declared = Number(req.headers['content-length']);
  if (Number.isFinite(declared) && declared > limit) throw new HttpError(413);
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw new HttpError(413);
    chunks.push(chunk);
  }
  return Buffer.concat(chunks, size);
}

async function handleKey(store, req, res, key) {
  switch (req.method) {
    case 'GET': {
      const value = store.get(key);
      if (value === undefined) return send(res, 404);
      return send(res, 200, value, { 'Content-Type': 'application/octet-stream' });
    }
    case 'PUT': {
      const value = await readBody(req, MAX_VALUE_BYTES);
      return send(res, store.set(key, value) ? 201 : 200);
    }
    case 'DELETE':
      return send(res, store.delete(key) ? 204 : 404);
    default:
      return methodNotAllowed(res, ['GET', 'PUT', 'DELETE']);
  }
}

async function route(store, req, res) {
  const path = req.url ?? '/';

  if (path === '/health') {
    if (req.method !== 'GET') return methodNotAllowed(res, ['GET']);
    return send(res, 200, 'ok', { 'Content-Type': 'text/plain' });
  }

  if (path === '/kv') {
    if (req.method !== 'GET') return methodNotAllowed(res, ['GET']);
    return send(res, 200, JSON.stringify(store.keys()), { 'Content-Type': 'application/json' });
  }

  if (path.startsWith(KV_PREFIX)) {
    const key = path.slice(KV_PREFIX.length);
    if (!KEY_RE.test(key)) return send(res, 400);
    return handleKey(store, req, res, key);
  }

  return send(res, 404);
}

export function createKvServer(store = new Store()) {
  const server = createServer({ keepAliveTimeout: 5000 }, (req, res) => {
    route(store, req, res).catch((err) => {
      const status = err instanceof HttpError ? err.status : 500;
      if (status === 500) console.error(err);
      if (res.headersSent) return res.destroy();
      // The unread remainder of the body makes the connection unusable; close it.
      send(res, status, '', { Connection: 'close' });
    });
  });
  return server;
}

/** In-memory key-value store holding raw byte values. */
export class Store {
  #data = new Map();

  /** @returns {boolean} true if the key was newly created */
  set(key, value) {
    const created = !this.#data.has(key);
    this.#data.set(key, value);
    return created;
  }

  get(key) {
    return this.#data.get(key);
  }

  delete(key) {
    return this.#data.delete(key);
  }

  keys() {
    // Keys are ASCII, so code-unit ordering is byte ordering.
    return [...this.#data.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  }
}

import { test } from 'node:test';
import { once } from 'node:events';
import { createKvServer } from '../src/server.js';

async function start(t) {
  const server = createKvServer().listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(() => server.close());
  const base = `http://127.0.0.1:${server.address().port}`;
  return (path, init) => fetch(base + path, init);
}

test('crud and listing', async (t) => {
  const req = await start(t);
  t.assert.equal((await req('/health')).status, 200);
  t.assert.equal((await req('/kv/b', { method: 'PUT', body: 'x' })).status, 201);
  t.assert.equal((await req('/kv/a', { method: 'PUT', body: new Uint8Array([0, 255]) })).status, 201);
  t.assert.equal((await req('/kv/a', { method: 'PUT', body: new Uint8Array([1, 254]) })).status, 200);
  t.assert.deepStrictEqual([...new Uint8Array(await (await req('/kv/a')).arrayBuffer())], [1, 254]);
  t.assert.deepStrictEqual(await (await req('/kv')).json(), ['a', 'b']);
  t.assert.equal((await req('/kv/a', { method: 'DELETE' })).status, 204);
  t.assert.equal((await req('/kv/a', { method: 'DELETE' })).status, 404);
  t.assert.equal((await req('/kv/a')).status, 404);
});

test('errors', async (t) => {
  const req = await start(t);
  t.assert.equal((await req('/nope')).status, 404);
  t.assert.equal((await req('/health', { method: 'POST' })).status, 405);
  t.assert.equal((await req('/kv', { method: 'DELETE' })).status, 405);
  t.assert.equal((await req('/kv/a', { method: 'PATCH' })).status, 405);
  for (const p of ['/kv/', '/kv/a/b', '/kv/bad.key', `/kv/${'x'.repeat(65)}`]) {
    t.assert.equal((await req(p)).status, 400, p);
  }
  t.assert.equal((await req(`/kv/${'x'.repeat(64)}`)).status, 404);
});
